<?php
// Administrator entry points provide $service, $selectedRun and $report.
$runId = (int) $selectedRun['id'];
$export = $service->exportRun($runId);
$stats = $report['statistics'] ?? [];
$categories = [];
foreach ($export['documents'] as $document) { $categories[$document['category']] = ($categories[$document['category']] ?? 0) + 1; }
$errorCounts = [];
foreach ($export['errors'] as $errorRow) { $errorCounts[$errorRow['category']][(int) $errorRow['output_id']] = true; }
$assigned = count($export['ratings']);
$submitted = count(array_filter($export['ratings'], static fn(array $row): bool => ($row['status'] ?? '') === 'submitted'));
$raters = count(array_unique(array_column($export['ratings'], 'evaluator_code')));
$metricCoverage = [];
foreach ($export['outputs'] as $output) {
    foreach ($output['metrics'] as $metric) {
        $name = $metric['name']; $status = $metric['status'];
        $metricCoverage[$name][$status] = ($metricCoverage[$name][$status] ?? 0) + 1;
    }
}
function ev_statistics_table(array $rows, string $caption, bool $human = false): void {
    ?><div class="table-wrap"><table><caption><?= ev_h($caption) ?></caption><thead><tr><th><?= $human ? 'Criterion' : 'Metric' ?></th><th>System</th><th>Mode</th><th>N attempted / valid / documents</th><th>Mean</th><th>Median</th><th>SD</th><th>Min / max</th><th>95% CI</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= ev_h(ev_label($row[$human ? 'criterion' : 'metric'] ?? '')) ?><br><small><?= ev_h($row['version'] ?? '') ?></small></td><td><?= ev_h($row['system']) ?></td><td><?= ev_h($row['mode']) ?></td><td><?= (int) $row['n_attempted'] ?> / <?= (int) $row['n_valid'] ?> / <?= (int) $row['n_documents'] ?></td><td class="numeric"><?= ev_number($row['mean']) ?></td><td class="numeric"><?= ev_number($row['median']) ?></td><td class="numeric"><?= ev_number($row['sd']) ?></td><td><?= ev_number($row['min']) ?> / <?= ev_number($row['max']) ?></td><td><?= !empty($row['ci_95']) ? ev_number($row['ci_95'][0]) . ' to ' . ev_number($row['ci_95'][1]) : 'Not estimable' ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="9">No measurements available for this table.</td></tr><?php endif; ?></tbody></table></div><?php
}
function ev_mode_comparison(array $rows): void {
    $matrix = [];
    foreach ($rows as $row) { if ($row['system'] === 'proposed') { $matrix[$row['metric'] . ' · ' . $row['version']][$row['mode']] = $row; } }
    ?><div class="table-wrap"><table><caption>Proposed system: summary modes (mean; valid N)</caption><thead><tr><th>Metric</th><?php foreach (['Brief', 'Balanced', 'Detailed', 'Comprehensive'] as $mode): ?><th><?= $mode ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($matrix as $metric => $modes): ?><tr><td><?= ev_h(ev_label($metric)) ?></td><?php foreach (['brief','balanced','detailed','comprehensive'] as $mode): $cell = $modes[$mode] ?? null; ?><td><?= $cell ? ev_number($cell['mean']) . '; N=' . (int) $cell['n_valid'] : 'Not evaluated' ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if (!$matrix): ?><tr><td colspan="5">No full-system mode measurements available.</td></tr><?php endif; ?></tbody></table></div><?php
}
function ev_system_comparison(array $rows): void {
    $matrix = [];
    foreach ($rows as $row) { if ($row['mode'] === 'balanced') { $matrix[$row['system']][$row['metric']][] = $row; } }
    $metrics = ['rouge_1' => 'ROUGE-1 F1', 'rouge_2' => 'ROUGE-2 F1', 'rouge_l' => 'ROUGE-L F1', 'bertscore' => 'BERTScore F1', 'critical_fact_preservation' => 'Fact preservation (%)', 'word_count' => 'Actual words'];
    ?><div class="table-wrap"><table><caption>System and ablation comparison: Balanced mode (mean; valid N)</caption><thead><tr><th>System / configuration</th><?php foreach ($metrics as $label): ?><th><?= ev_h($label) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($matrix as $system => $values): ?><tr><td><?= ev_h($system) ?></td><?php foreach ($metrics as $metric => $label): $versions = $values[$metric] ?? []; $cell = count($versions) === 1 ? $versions[0] : null; ?><td><?= count($versions) > 1 ? 'Multiple versions; see detailed table' : ($cell ? ev_number($cell['mean']) . '; N=' . (int) $cell['n_valid'] : 'Not evaluated') ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if (!$matrix): ?><tr><td colspan="7">Balanced mode was not evaluated in this run.</td></tr><?php endif; ?></tbody></table></div><?php
}
?>
<section class="evaluation-section"><h2>Evaluation report: <?= ev_h($selectedRun['name']) ?></h2><div class="evaluation-actions"><a href="evaluation_export.php?run=<?= $runId ?>&format=json">Download JSON</a><a href="evaluation_export.php?run=<?= $runId ?>&format=csv">Download CSV</a><a href="evaluation_export.php?run=<?= $runId ?>&format=html">Printable report</a></div>
<dl class="evaluation-meta"><?php foreach (['Dataset version' => $selectedRun['dataset_version'], 'Split' => $selectedRun['dataset_split'], 'Run status' => ev_label($selectedRun['status']), 'Run identifier' => $selectedRun['run_uuid'], 'Started (UTC)' => $selectedRun['started_at'] ?? 'Not started', 'Completed (UTC)' => $selectedRun['completed_at'] ?? 'Not completed', 'Summarizer version' => $selectedRun['summarizer_version'], 'Evaluation version' => $selectedRun['evaluation_version'], 'Configuration SHA-256' => $selectedRun['configuration_hash'], 'Dataset snapshot SHA-256' => $selectedRun['snapshot_hash']] as $label => $value): ?><dt><?= ev_h($label) ?></dt><dd><?= ev_h($value) ?></dd><?php endforeach; ?></dl>
<p><?= count($export['documents']) ?> source documents; <?= (int) $report['outputs_total'] ?> planned outputs; <?= (int) $report['generated_summaries'] ?> generated; <?= (int) $report['failed_summaries'] ?> generation failures.</p><p><?php foreach ($categories as $category => $count): ?><?= ev_h(ev_label($category)) ?>: <?= $count ?>. <?php endforeach; ?></p>
<?php if ($report['pending']): ?><p class="evaluation-notice" role="status">The statistical report is awaiting an offline refresh. Any tables below reflect the last completed calculation and may exclude recent ratings or annotations.</p><?php endif; ?>
<?php if (!empty($selectedRun['error_message'])): ?><p class="analytics-alert">Run limitation: <?= ev_h($selectedRun['error_message']) ?></p><?php endif; ?>
<?php if ($report['error']): ?><p class="analytics-alert">Statistical report unavailable: <?= ev_h($report['error']) ?></p><?php endif; ?>
<p class="evaluation-note">These measures describe different properties; none is an overall accuracy percentage. Results from a validation split must not be presented as held-out test performance.</p></section>
<section class="evaluation-section"><h2>Metric availability</h2><div class="table-wrap"><table><thead><tr><th>Metric</th><th>Valid</th><th>Unavailable</th><th>Not applicable</th><th>Error</th><th>Not recorded</th></tr></thead><tbody><?php foreach ($metricCoverage as $name => $coverage): ?><tr><td><?= ev_h(ev_label($name)) ?></td><td><?= (int) ($coverage['ok'] ?? 0) ?></td><td><?= (int) ($coverage['unavailable'] ?? 0) ?></td><td><?= (int) ($coverage['not_applicable'] ?? 0) ?></td><td><?= (int) ($coverage['error'] ?? 0) ?></td><td><?= max(0, (int) $report['outputs_total'] - array_sum($coverage)) ?></td></tr><?php endforeach; ?><?php if (!$metricCoverage): ?><tr><td colspan="6">No metric records yet. Missing measurements are never replaced with zero.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="evaluation-section"><h2>System, baseline, length, and ablation comparisons</h2><p class="evaluation-note">ROUGE and BERTScore use F1 on a 0–1 scale. Compression ratio and redundancy use 0–1; compression percentage and critical-fact preservation use percent. Factual consistency is the documented heuristic’s 0–1 result. Performance measurements use seconds. Mean, median, SD, range, and intervals summarize document-level means. N valid counts individual measurements before aggregation; documents are the sampling unit. Ablated systems are identified by their disabled feature.</p>
<?php ev_system_comparison($stats['automatic'] ?? []); ev_mode_comparison($stats['automatic'] ?? []); ?>
<details><summary>All automatic measurements, sample sizes, and confidence intervals</summary><?php ev_statistics_table($stats['automatic'] ?? [], 'Automatic measurements by system and summary mode'); ?></details>
<?php if (!empty($stats['automatic'])): ?><details><summary>View compression by mode</summary><div class="evaluation-chart"><canvas id="evaluation-compression-chart" aria-label="Mean compression ratio by system and mode. Values are also in the automatic measurements table." role="img"></canvas></div></details><?php endif; ?>
</section>
<section class="evaluation-section"><h2>Human evaluation</h2><p><?= $submitted ?> of <?= $assigned ?> assigned assessments submitted; <?= $raters ?> assigned evaluators. Required dimensions use a five-point Likert scale. Descriptive statistics summarize document means after averaging available submitted raters; they are not pooled individual-rating statistics. Intervals condition on this evaluator panel. Only submitted assessments enter quality estimates; missing assignments remain in coverage counts.</p><?php ev_statistics_table($stats['human'] ?? [], 'Human judgments by criterion, system, and mode', true); ?></section>
<section class="evaluation-section"><h2>Inter-rater agreement</h2><p class="evaluation-note">Ordinal Krippendorff’s alpha measures reliability of the ratings, not summary quality. Constant or insufficient ratings can make alpha undefined. Inspect missingness and the number of pairable items before interpreting it.</p><div class="table-wrap"><table><thead><tr><th>Criterion</th><th>Statistic</th><th>Alpha</th><th>Raters</th><th>Items / pairable</th><th>Ratings / unsubmitted assigned / unassigned slots</th><th>Status</th></tr></thead><tbody><?php foreach ($stats['agreement'] ?? [] as $row): ?><tr><td><?= ev_h(ev_label($row['criterion'])) ?></td><td><?= ev_h($row['statistic']) ?> (<?= ev_h($row['level']) ?>)</td><td><?= ev_number($row['value']) ?></td><td><?= (int) $row['n_raters'] ?></td><td><?= (int) $row['n_items'] ?> / <?= (int) $row['n_pairable_items'] ?></td><td><?= (int) $row['n_ratings'] ?> / <?= (int) ($row['unsubmitted_assigned_ratings'] ?? 0) ?> / <?= (int) ($row['unassigned_matrix_slots'] ?? 0) ?></td><td><?= ev_h($row['status']) ?></td></tr><?php endforeach; ?><?php if (empty($stats['agreement'])): ?><tr><td colspan="7">Independent ratings are needed before reliability can be calculated.</td></tr><?php endif; ?></tbody></table></div></section>
<details class="evaluation-section"><summary>Paired statistical comparisons</summary><p class="evaluation-note">Configured two-sided Wilcoxon signed-rank comparisons use paired documents and Holm correction within reported comparison families, with α = 0.05. The signed-rank test assumes independent documents and symmetric paired differences. Effect size is rank-biserial correlation. Treat these comparisons as exploratory unless the research team fixed them in an analysis plan before inspecting results. Statistical significance alone does not establish practical quality or superiority. Actual lengths can change under ablation; inspect word counts before attributing differences solely to a component.</p><div class="table-wrap"><table><thead><tr><th>Metric / context</th><th>Left / right</th><th>N attempted / paired / nonzero / unpaired</th><th>Mean difference</th><th>p / Holm p</th><th>Effect size</th><th>Status</th></tr></thead><tbody><?php foreach ($stats['comparisons'] ?? [] as $row): ?><tr><td><?= ev_h($row['metric']) ?> · <?= ev_h($row['mode'] ?? $row['system'] ?? '') ?></td><td><?= ev_h($row['left']) ?> / <?= ev_h($row['right']) ?></td><td><?= (int) ($row['n_candidate_documents'] ?? $row['n_paired']) ?> / <?= (int) $row['n_paired'] ?> / <?= (int) ($row['n_nonzero_pairs'] ?? 0) ?> / <?= (int) $row['n_unpaired'] ?></td><td><?= ev_number($row['mean_difference'] ?? null) ?></td><td><?= ev_h(ev_pvalue($row['p_value'] ?? null)) ?> / <?= ev_h(ev_pvalue($row['p_adjusted'] ?? null)) ?><br><small>Holm family: <?= ev_h($row['correction_family'] ?? '') ?>; <?= (int) ($row['family_tests'] ?? 0) ?> tests</small></td><td><?= ev_number($row['effect_size'] ?? null) ?></td><td><?= ev_h($row['status']) ?></td></tr><?php endforeach; ?><?php if (empty($stats['comparisons'])): ?><tr><td colspan="7">No paired comparison is available.</td></tr><?php endif; ?></tbody></table></div></details>
<section class="evaluation-section"><h2>Error analysis and representative observations</h2><p class="evaluation-note">Counts are distinct outputs with a reviewer-recorded category. Percentages use generated outputs as the denominator. Categories can overlap. An unreviewed output is not evidence of an error-free output.</p><div class="table-wrap"><table><thead><tr><th>Error category</th><th>Outputs</th><th>Percent of generated outputs</th></tr></thead><tbody><?php foreach ($errorCounts as $category => $ids): ?><tr><td><?= ev_h(ev_label($category)) ?></td><td><?= count($ids) ?></td><td><?= (int) $report['generated_summaries'] > 0 ? ev_number(count($ids) / (int) $report['generated_summaries'] * 100, 1) . '%' : 'Not applicable' ?></td></tr><?php endforeach; ?><?php if (!$errorCounts): ?><tr><td colspan="3">No reviewer classifications recorded.</td></tr><?php endif; ?></tbody></table></div>
<?php foreach (array_slice($export['errors'], 0, 10) as $example): ?><p><a href="evaluation.php?tab=output&id=<?= (int) $example['output_id'] ?>">Output <?= (int) $example['output_id'] ?></a> — <?= ev_h(ev_label($example['category'])) ?>: <?= ev_h($example['notes']) ?></p><?php endforeach; ?></section>
<section class="evaluation-section"><h2>Challenge tests</h2><div class="table-wrap"><table><thead><tr><th>Output</th><th>System / mode</th><th>Status</th><th>Assertions passed</th><th>Failure evidence</th></tr></thead><tbody><?php $challengeRows = 0; foreach ($export['outputs'] as $output): foreach ($output['metrics'] as $metric): if ($metric['name'] !== 'challenge' || $metric['status'] === 'not_applicable') { continue; } $challengeRows++; $details = $metric['details']; ?><tr><td><a href="evaluation.php?tab=output&id=<?= (int) $output['id'] ?>"><?= (int) $output['id'] ?></a></td><td><?= ev_h($output['system_name']) ?> / <?= ev_h($output['mode']) ?></td><td><?= ev_h($metric['status']) ?></td><td><?= isset($details['cases_total']) ? ((int) $details['cases_passed'] . ' / ' . (int) $details['cases_total'] . ' cases') : (isset($details['passed']) ? ($details['passed'] ? 'Pass' : 'Fail') : ev_number($metric['value'])) ?></td><td><?= ev_h($metric['error'] ?? $details['failure_reason'] ?? '') ?><?php foreach ($details['missing_expected_phrases'] ?? [] as $phrase): ?><p>Missing: <?= ev_h($phrase) ?></p><?php endforeach; foreach ($details['prohibited_distortions_found'] ?? [] as $phrase): ?><p>Prohibited: <?= ev_h($phrase) ?></p><?php endforeach; foreach ($details['cases'] ?? [] as $case): if (($case['passed'] ?? false) === true) { continue; } ?><p>Case <?= ev_h($case['id'] ?? '') ?> ? <?= ev_h($case['category'] ?? '') ?></p><?php foreach ($case['missing_expected_phrases'] ?? [] as $phrase): ?><p>Missing: <?= ev_h($phrase) ?></p><?php endforeach; foreach ($case['prohibited_distortions_found'] ?? [] as $phrase): ?><p>Prohibited: <?= ev_h($phrase) ?></p><?php endforeach; endforeach; ?></td></tr><?php endforeach; endforeach; if (!$challengeRows): ?><tr><td colspan="5">No challenge measurements recorded for this run.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="evaluation-section"><h2>Limitations and interpretation</h2><p>This report makes descriptive measurements. Researchers must interpret differences, assess length fairness, and document selection bias, reference subjectivity, and any observed source-processing failures.</p><dl class="evaluation-meta"><dt>Observed limitations</dt><dd><?= $errorCounts ? 'See recorded error categories and source-linked examples above.' : 'No reviewer observations have been recorded yet.' ?></dd><dt>Human evidence</dt><dd><?= $submitted ? 'Interpret with the evaluator and document counts shown above.' : 'No submitted human ratings; human quality conclusions are not available.' ?></dd><dt>References</dt><dd>Overlap and semantic metrics depend on approved independent references. Availability is shown per metric.</dd><dt>Factuality</dt><dd>Rule-based checks do not establish entailment, causal validity, or complete entity resolution.</dd><dt>Manuscript preparation</dt><dd>Report the actual split, sampling protocol, versions, denominators, test assumptions, and observed limitations. Do not treat validation fixtures as a final evaluation corpus.</dd></dl>
<?php foreach ($stats['warnings'] ?? [] as $warning): ?><p class="evaluation-note"><?= ev_h($warning) ?></p><?php endforeach; ?></section>
<?php if (!empty($stats['automatic'])): ?><script type="application/json" id="evaluation-chart-data"><?= json_encode($stats['automatic'], JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?></script><script src="assets/js/vendor/chart.umd.min.js"></script><script src="assets/js/evaluation.js"></script><?php endif; ?>
